window.EP = {"name": "ch12", "label": "एपिसोड 12", "en": "The Doctor Who Knew Who Would Die", "duration": 1151.21, "title": [{"start": 5.5, "end": 6.88, "text": "हिडन उत्तराखंड"}, {"start": 7.43, "end": 10.18, "text": "अ बुक बाय, पार्थ डी. जोशी"}, {"start": 10.73, "end": 15.39, "text": "चैप्टर ट्वेल्व। द डॉक्टर हू न्यू हू वुड डाई"}, {"start": 15.94, "end": 18.09, "text": "डे ट्वेल्व। एबट माउंट"}], "captions": [{"start": 19.64, "end": 23.8, "text": "मैसेज रात आठ बजकर सैंतालीस मिनट पर मेरे फ़ोन पर आया।", "who": "", "voice": "narrator", "diary": false}, {"start": 24.25, "end": 25.29, "text": "लड़की ठीक है।", "who": "", "voice": "narrator", "diary": false}, {"start": 25.29, "end": 28.48, "text": "डरी हुई भी नहीं है, जो थोड़ा एनॉयिंग है।", "who": "", "voice": "narrator", "diary": false}, {"start": 28.48, "end": 29.12, "text": "आधी रात।", "who": "", "voice": "narrator", "diary": false}, {"start": 29.12, "end": 30.64, "text": "एबट माउंट, लोहाघाट।", "who": "", "voice": "narrator", "diary": false}, {"start": 30.64, "end": 31.68, "text": "पुराना बंगला।", "who": "", "voice": "narrator", "diary": false}, {"start": 31.68, "end": 33.6, "text": "लड़के की डायरी लेके आना।", "who": "", "voice": "narrator", "diary": false}, {"start": 33.6, "end": 37.44, "text": "हाँ, प्रोफ़ेसर, मुझे पता है, असली दिमाग़ कौन है।", "who": "", "voice": "narrator", "diary": false}, {"start": 37.44, "end": 38.31, "text": "पुलिस नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 38.31, "end": 39.43, "text": "कमांडेंट नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 39.43, "end": 40.63, "text": "सिर्फ़ तुम तीन।", "who": "", "voice": "narrator", "diary": false}, {"start": 40.63, "end": 41.75, "text": "और वो ड्राइवर।", "who": "", "voice": "narrator", "diary": false}, {"start": 41.75, "end": 41.99, "text": "आर.", "who": "", "voice": "narrator", "diary": false}, {"start": 42.44, "end": 45.37, "text": "क्षितिज ने उसे मेरे कंधे के ऊपर से पढ़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 45.37, "end": 46.69, "text": "उसने कुछ नहीं कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 46.69, "end": 50.43, "text": "उसने बस अपनी डायरी के कवर पर अपना हाथ सपाट रख दिया,", "who": "", "voice": "narrator", "diary": false}, {"start": 50.43, "end": 54.1, "text": "उस तरह, जैसे आप किसी बच्चे के सिर पर हाथ रखते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 55.6, "end": 58.7, "text": "गब्बर अँधेरे में, ढाबे की पार्किंग के किनारे,", "who": "", "voice": "narrator", "diary": false}, {"start": 58.7, "end": 60.84, "text": "बसंती के बोनट पर अकेले बैठे थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 60.84, "end": 62.22, "text": "जब मैं उनके पास गया,", "who": "", "voice": "narrator", "diary": false}, {"start": 62.22, "end": 66.02, "text": "उन्होंने मेरे मुँह खोलने से पहले ही बोलना शुरू कर दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 66.47, "end": 67.18, "text": "महेश।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 67.38, "end": 70.31, "text": "उन्होंने ज़मीन को घूरते हुए कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 70.51, "end": 71.67, "text": "मेरे मामा का बेटा।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 71.67, "end": 72.84, "text": "बचपन साथ में बीता।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 73.04, "end": 74.14, "text": "उन्होंने थूक निगला।", "who": "", "voice": "narrator", "diary": false}, {"start": 74.34, "end": 77.52, "text": "सहगल ने उसको पैसा दिया, प्रोफ़ेसर साहब।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 77.52, "end": 78.5, "text": "पहले दिन से।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 78.5, "end": 80.95, "text": "मैंने उसे द्रोणागिरी का बताया।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 80.95, "end": 82.67, "text": "इजा के गाँव का बताया।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 82.67, "end": 85.28, "text": "कल रात गंगोलीहाट का भी बता दिया।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 85.28, "end": 85.77, "text": "और आज…", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 85.97, "end": 87.88, "text": "उनकी आवाज़ टूट गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 88.08, "end": 91.44, "text": "आज मैंने उसे फ़ोन करके गाली दी, और ग़ुस्से में बोल दिया,", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 91.44, "end": 93.47, "text": "मैं गंगोलीहाट में हूँ, आके देख ले।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 93.47, "end": 95.33, "text": "वो लोग तो पहले से वहीं बैठे थे।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 95.78, "end": 98.39, "text": "वो हँसे: एक भद्दी, टूटी हुई आवाज़।", "who": "", "voice": "narrator", "diary": false}, {"start": 98.84, "end": 100.99, "text": "गब्बर ने ख़ुद सहगल को बताया।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 100.99, "end": 102.52, "text": "बसंती के ड्राइवर ने।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 102.97, "end": 104.81, "text": "मैं उनके बग़ल में बोनट पर बैठ गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 105.26, "end": 108.26, "text": "मेरे स्टूडेंट्स ने चीटिंग की है, झूठ बोला है,", "who": "", "voice": "narrator", "diary": false}, {"start": 108.26, "end": 111.53, "text": "यूट्यूब से पूरे के पूरे प्रोजेक्ट्स कॉपी किए हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 111.53, "end": 114.8, "text": "मेरे एक कलीग ने मेरे काम पर अपना नाम लिख दिया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 114.8, "end": 117.33, "text": "मुझे पता है, जिस पर आप भरोसा करते हैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 117.33, "end": 119.2, "text": "उससे धोखा खाना कैसा लगता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 119.2, "end": 122.14, "text": "मेरे पास कहने को कोई समझदारी की बात नहीं थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 122.59, "end": 125.53, "text": "तो मैंने वो कहा, जो मेरे पास सबसे सच्चा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 125.98, "end": 126.77, "text": "गब्बर भाई।", "who": "", "voice": "narrator", "diary": false}, {"start": 126.77, "end": 131.06, "text": "पहले दिन आपने कहा था, बसंती ने इससे बुरे लोग देखे हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 131.06, "end": 132.65, "text": "मुझे लगा, मज़ाक़ था।", "who": "", "voice": "narrator", "diary": false}, {"start": 132.85, "end": 136.13, "text": "मैंने अपने कंधे से उनके कंधे को हल्का सा धक्का दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 136.33, "end": 136.76, "text": "अब चलो।", "who": "", "voice": "narrator", "diary": false}, {"start": 136.76, "end": 139.69, "text": "बसंती को दिखाते हैं, कि बुरे लोग कैसे भागते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 140.14, "end": 141.67, "text": "उन्होंने मुझे देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 141.67, "end": 145.84, "text": "धीरे से, बहुत धीरे से, उनकी मूँछ का एक कोना ऊपर उठा।", "who": "", "voice": "narrator", "diary": false}, {"start": 146.29, "end": 149.32, "text": "ठीक तभी, सफ़ेद एस-यू-वी पार्किंग में दाख़िल हुई।", "who": "", "voice": "narrator", "diary": false}, {"start": 149.77, "end": 150.7, "text": "गोलू उतरा।", "who": "", "voice": "narrator", "diary": false}, {"start": 150.7, "end": 152.48, "text": "कोई रिंग लाइट नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 152.48, "end": 155.09, "text": "कोई यूट्यूब वाली आवाज़ नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 155.09, "end": 160.89, "text": "वो सीधा हमारे पास आया, अपना फ़ोन आगे बढ़ाया, और बस एक बात कही।", "who": "", "voice": "narrator", "diary": false}, {"start": 161.34, "end": 162.33, "text": "दीदी का पता है मुझे।", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 162.78, "end": 164.92, "text": "स्क्रीन पर एक मैप था।", "who": "", "voice": "narrator", "diary": false}, {"start": 164.92, "end": 167.77, "text": "लोहाघाट के ऊपर एक पहाड़ी पर,", "who": "", "voice": "narrator", "diary": false}, {"start": 167.77, "end": 171.54, "text": "एक छोटा सा नीला बिंदु, टिमटिमाता हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 171.54, "end": 176.93, "text": "और उसके पीछे, एक लंबी, भटकती हुई नीली लाइन, एक निशान,", "who": "", "voice": "narrator", "diary": false}, {"start": 176.93, "end": 183.35, "text": "जो ज़ूम आउट करने पर, पूरे कुमाऊँ और गढ़वाल के पार पीछे जाता था।", "who": "", "voice": "narrator", "diary": false}, {"start": 183.35, "end": 184.36, "text": "गंगोलीहाट।", "who": "", "voice": "narrator", "diary": false}, {"start": 184.36, "end": 185.28, "text": "बागेश्वर।", "who": "", "voice": "narrator", "diary": false}, {"start": 185.28, "end": 185.69, "text": "वान।", "who": "", "voice": "narrator", "diary": false}, {"start": 185.69, "end": 186.4, "text": "जोशीमठ।", "who": "", "voice": "narrator", "diary": false}, {"start": 186.4, "end": 187.01, "text": "चोपता।", "who": "", "voice": "narrator", "diary": false}, {"start": 187.01, "end": 188.03, "text": "देवप्रयाग।", "who": "", "voice": "narrator", "diary": false}, {"start": 188.73, "end": 189.35, "text": "मसूरी।", "who": "", "voice": "narrator", "diary": false}, {"start": 190.05, "end": 191.73, "text": "जी-पी-एस ट्रैकर।", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 191.93, "end": 192.97, "text": "गोलू ने मुझे बताया।", "who": "", "voice": "narrator", "diary": false}, {"start": 193.17, "end": 195.16, "text": "रोहन की गाड़ी के नीचे।", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 195.16, "end": 197.33, "text": "सवॉय की रात को लगाया था।", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 197.33, "end": 199.58, "text": "जब सब स्पून्स उठा रहे थे।", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 200.28, "end": 202.04, "text": "देर तक किसी ने कुछ नहीं कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 202.74, "end": 204.55, "text": "फिर क्षितिज आगे बढ़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 204.55, "end": 208.06, "text": "वो गले लगाने वाला इंसान नहीं है, क्षितिज।", "who": "", "voice": "narrator", "diary": false}, {"start": 208.06, "end": 210.81, "text": "लेकिन वो गोलू के सामने खड़ा हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 210.81, "end": 214.5, "text": "उसकी आँखों में देखा, और बहुत साफ़-साफ़ कहा:", "who": "", "voice": "narrator", "diary": false}, {"start": 214.95, "end": 215.36, "text": "सॉरी।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 215.36, "end": 216.34, "text": "मैं ग़लत था।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 216.79, "end": 218.66, "text": "कोई नंबर्ड पॉइंट्स नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 218.66, "end": 219.83, "text": "कोई डायरी नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 219.83, "end": 224.34, "text": "बस तीन शब्द, उसी तरह, जैसे उसकी बहन ने उसे कहने को कहा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 224.34, "end": 226.82, "text": "उसके ग़ायब होने से छह मिनट पहले।", "who": "", "voice": "narrator", "diary": false}, {"start": 227.27, "end": 229.18, "text": "गोलू की आवाज़ भर्राई हुई थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 229.38, "end": 229.97, "text": "बाद में।", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 229.97, "end": 230.7, "text": "पहले दीदी।", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 231.15, "end": 235.4, "text": "तब मैंने उसे देखा, ढंग से, बारह दिनों में पहली बार।", "who": "", "voice": "narrator", "diary": false}, {"start": 235.4, "end": 239.73, "text": "पफ़र जैकेट को नहीं, जिम्बल को नहीं, उस आदमी को नहीं,", "who": "", "voice": "narrator", "diary": false}, {"start": 239.73, "end": 243.47, "text": "जिसने मुझे अननोन एंटिटी, फ़ीमेल, बना दिया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 243.47, "end": 249.3, "text": "लाल आँखों और एक पुरानी नीली टोपी वाले एक थके हुए, जवान पहाड़ी आदमी को,", "who": "", "voice": "narrator", "diary": false}, {"start": 249.3, "end": 251.05, "text": "जो किसी को बताए बिना,", "who": "", "voice": "narrator", "diary": false}, {"start": 251.05, "end": 255.21, "text": "एक पूरे राज्य के पार एक गाड़ी का पीछा करता रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 255.66, "end": 258.94, "text": "मुझे अभी नहीं पता था, कि वो कौन है।", "who": "", "voice": "narrator", "diary": false}, {"start": 258.94, "end": 260.62, "text": "मुझे काफ़ी पता था।", "who": "", "voice": "narrator", "diary": false}, {"start": 261.07, "end": 261.54, "text": "बाद में।", "who": "", "voice": "narrator", "diary": false}, {"start": 261.74, "end": 262.7, "text": "मैंने हामी भरी।", "who": "", "voice": "narrator", "diary": false}, {"start": 262.9, "end": 263.77, "text": "पहले शाओनी।", "who": "", "voice": "narrator", "diary": false}, {"start": 265.27, "end": 272.51, "text": "एबट माउंट, चंपावत ज़िले में, लोहाघाट के ऊपर एक धार पर है: देवदार और बाँज के बीच बिखरे,", "who": "", "voice": "narrator", "diary": false}, {"start": 272.51, "end": 275.63, "text": "अंग्रेज़ों के ज़माने के पुराने कॉटेज,", "who": "", "voice": "narrator", "diary": false}, {"start": 275.63, "end": 280.6, "text": "जो औपनिवेशिक दिनों में पहाड़ी आरामगाह के तौर पर बनाए गए थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 280.6, "end": 284.39, "text": "दिन में, गब्बर ने हमें बताया, ये ख़ूबसूरत है।", "who": "", "voice": "narrator", "diary": false}, {"start": 284.39, "end": 284.81, "text": "शांत।", "who": "", "voice": "narrator", "diary": false}, {"start": 284.81, "end": 287.67, "text": "लॉन से बर्फ़ीली चोटियों के नज़ारे।", "who": "", "voice": "narrator", "diary": false}, {"start": 288.12, "end": 289.31, "text": "रात को।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 289.51, "end": 290.15, "text": "उन्होंने कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 290.35, "end": 292.25, "text": "लोग वहाँ नहीं जाते।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 292.7, "end": 293.12, "text": "क्यों?", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 293.32, "end": 295.49, "text": "क्षितिज ने पीछे की सीट से पूछा।", "who": "", "voice": "narrator", "diary": false}, {"start": 295.49, "end": 298.29, "text": "वो एक ढाबे के मेन्यू के पीछे लिख रहा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 298.29, "end": 300.32, "text": "क्योंकि उसकी डायरी फिरौती थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 300.77, "end": 303.44, "text": "और जैसे-जैसे हम अँधेरे में ऊपर चढ़े,", "who": "", "voice": "narrator", "diary": false}, {"start": 303.44, "end": 307.73, "text": "गब्बर ने हमें कहानी सुनाई, उसी तरह, जैसे उन्होंने सुनी थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 308.18, "end": 312.51, "text": "कहानी कहती है, कि धार पर की पुरानी इमारतों में से एक,", "who": "", "voice": "narrator", "diary": false}, {"start": 312.51, "end": 314.72, "text": "कभी एक अस्पताल हुआ करती थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 314.72, "end": 317.99, "text": "उसे चलाने वाले डॉक्टर के पास एक हुनर था,", "who": "", "voice": "narrator", "diary": false}, {"start": 317.99, "end": 322.15, "text": "या एक श्राप: वो किसी मरीज़ को बस देखकर बता सकता था,", "who": "", "voice": "narrator", "diary": false}, {"start": 322.15, "end": 323.79, "text": "कि कौन मरने वाला है।", "who": "", "voice": "narrator", "diary": false}, {"start": 323.79, "end": 326.89, "text": "और जब उसे ये दिखता, तो वो उस मरीज़ को,", "who": "", "voice": "narrator", "diary": false}, {"start": 326.89, "end": 330.33, "text": "बाक़ियों से अलग, एक ख़ास कमरे में ले जाता।", "who": "", "voice": "narrator", "diary": false}, {"start": 330.33, "end": 334.0, "text": "लोग उसे मुक्ति कोठरी कहते थे, मुक्ति का कमरा।", "who": "", "voice": "narrator", "diary": false}, {"start": 334.0, "end": 338.09, "text": "कथा कहती है, कि जो मरीज़ अंदर गए, वो बाहर नहीं आए।", "who": "", "voice": "narrator", "diary": false}, {"start": 338.09, "end": 345.61, "text": "और कुछ ख़ास रातों में, लोहाघाट के लोग आज भी कहते हैं, कि उन्हें वहाँ ऊपर रोशनियाँ दिखती हैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 345.61, "end": 349.94, "text": "और ऐसी चीज़ें सुनाई देती हैं, जो वो सुनना नहीं चाहते।", "who": "", "voice": "narrator", "diary": false}, {"start": 350.39, "end": 351.28, "text": "सच है?", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 351.48, "end": 352.82, "text": "क्षितिज ने उनसे पूछा।", "who": "", "voice": "narrator", "diary": false}, {"start": 353.27, "end": 353.97, "text": "कहानी है।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 354.17, "end": 355.28, "text": "गब्बर ने उससे कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 355.48, "end": 359.21, "text": "पहाड़ की कहानियाँ, सच से पुरानी होती हैं।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 359.66, "end": 361.7, "text": "मैं आपसे ईमानदार रहूँगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 361.7, "end": 364.51, "text": "मैंने ये पता करने की कोशिश की है,", "who": "", "voice": "narrator", "diary": false}, {"start": 364.51, "end": 369.61, "text": "कि उस धार पर असल में क्या हुआ था, और मैं आपको नहीं बता सकता।", "who": "", "voice": "narrator", "diary": false}, {"start": 369.61, "end": 372.75, "text": "रिकॉर्ड्स पतले हैं, और कहानियाँ मोटी।", "who": "", "voice": "narrator", "diary": false}, {"start": 372.75, "end": 375.47, "text": "तो इस किताब में, वो वही रहती है,", "who": "", "voice": "narrator", "diary": false}, {"start": 375.47, "end": 378.19, "text": "जो वो लोहाघाट में है: एक दंतकथा।", "who": "", "voice": "narrator", "diary": false}, {"start": 378.19, "end": 380.65, "text": "लेकिन मैं आपको ये भी बताऊँगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 380.65, "end": 387.88, "text": "जब हम धार के नीचे, धुंध में, सवा ग्यारह बजे गाड़ी से उतरे, हर पेड़ से पानी टपकता हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 387.88, "end": 393.23, "text": "और हर परछाईं हिलती हुई, तो मैं मुक्ति के कमरे को मना नहीं करता।", "who": "", "voice": "narrator", "diary": false}, {"start": 393.23, "end": 396.88, "text": "ख़ासकर, ताले वाले एक कमरे को, अहमदाबाद में।", "who": "", "voice": "narrator", "diary": false}, {"start": 398.38, "end": 400.79, "text": "गब्बर गीली घास में उकड़ूँ बैठे,", "who": "", "voice": "narrator", "diary": false}, {"start": 400.79, "end": 406.22, "text": "और हम तीनों को किसी क्रिकेट कैप्टन की तरह अपने चारों तरफ़ इकट्ठा किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 406.67, "end": 408.27, "text": "भल्ला भूत से डरता है।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 408.47, "end": 409.09, "text": "उन्होंने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 409.29, "end": 409.76, "text": "पक्का।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 409.76, "end": 410.69, "text": "घाट पे भागा।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 410.69, "end": 414.72, "text": "भगुवाबासा में दीदी की आवाज़ सुन के टेंट में छुप गया।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 414.92, "end": 416.92, "text": "अँधेरे में उनकी आँखें चमकीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 417.12, "end": 420.21, "text": "तो आज हम उसे एक भूत नहीं दिखाएँगे।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 420.66, "end": 420.96, "text": "तो?", "who": "", "voice": "narrator", "diary": false}, {"start": 421.16, "end": 422.18, "text": "मैंने उनसे पूछा।", "who": "", "voice": "narrator", "diary": false}, {"start": 422.63, "end": 424.39, "text": "एक देवता दिखाएँगे।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 424.84, "end": 427.08, "text": "और उन्होंने हमें ऐड़ी के बारे में बताया।", "who": "", "voice": "narrator", "diary": false}, {"start": 427.53, "end": 435.45, "text": "ऐड़ी, कुमाऊँ के सबसे ज़्यादा डराने वाले, और सबसे ज़्यादा पूजे जाने वाले लोक-देवताओं में से एक हैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 435.45, "end": 438.77, "text": "उन्होंने कहा: जंगलों और चरवाहों के देवता,", "who": "", "voice": "narrator", "diary": false}, {"start": 438.77, "end": 441.35, "text": "जिनकी आँखें उनके सिर के ऊपर हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 441.35, "end": 444.43, "text": "दिन में वो घने जंगल में छुपे रहते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 444.43, "end": 451.54, "text": "लेकिन रात को, वो एक डोली में, अँधेरे में उठाए हुए, जंगलों और धारों के ऊपर से निकलते हैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 451.54, "end": 454.21, "text": "डोली के साथ दो कुत्ते दौड़ते हुए,", "who": "", "voice": "narrator", "diary": false}, {"start": 454.21, "end": 456.88, "text": "और पूरे रास्ते घंटियाँ बजती हुईं।", "who": "", "voice": "narrator", "diary": false}, {"start": 456.88, "end": 462.05, "text": "डोली के दोनों तरफ़, दो डायन-रक्षिकाएँ चलती हैं, आँछरी और चाँछरी।", "who": "", "voice": "narrator", "diary": false}, {"start": 462.05, "end": 466.17, "text": "पीछे ऐसी आत्माएँ आती हैं, जिनके पैर उल्टे होते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 466.17, "end": 470.54, "text": "और कहा जाता है, कि जो कोई रात को ऐड़ी की सवारी देख ले,", "who": "", "voice": "narrator", "diary": false}, {"start": 470.54, "end": 472.32, "text": "वो उसी जगह मर जाता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 472.77, "end": 473.86, "text": "क्षितिज को शक था।", "who": "", "voice": "narrator", "diary": false}, {"start": 474.06, "end": 475.69, "text": "भल्ला ने ये कहानी सुनी होगी?", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 476.14, "end": 477.56, "text": "हर पहाड़ी ने सुनी है।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 477.76, "end": 478.87, "text": "गब्बर ने उससे कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 479.07, "end": 480.65, "text": "और भल्ला पहाड़ी है।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 480.65, "end": 482.3, "text": "उसका लहजा सुना नहीं?", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 482.3, "end": 483.63, "text": "पिथौरागढ़ का है।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 483.63, "end": 487.1, "text": "बचपन में उसकी दादी ने ये कहानी सुनाई होगी।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 487.1, "end": 487.68, "text": "रात को।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 487.68, "end": 488.51, "text": "रज़ाई में।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 488.71, "end": 489.67, "text": "वो मुस्कुराए।", "who": "", "voice": "narrator", "diary": false}, {"start": 489.87, "end": 492.03, "text": "बचपन का डर कभी नहीं जाता, प्रोफ़ेसर साहब।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 492.48, "end": 494.8, "text": "विलेन्स के बारे में यही बात है, रीडर।", "who": "", "voice": "narrator", "diary": false}, {"start": 494.8, "end": 497.18, "text": "फ़िल्मों में, उनकी दादियाँ नहीं होतीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 497.18, "end": 499.12, "text": "असल ज़िंदगी में, सबकी होती हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 499.57, "end": 501.37, "text": "हमारे पास पैंतालीस मिनट थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 501.37, "end": 506.29, "text": "तो ये रहा, कि दो बड़े आदमी, एक बिना डायरी का क्लू फ़ाइंडर, और एक यूट्यूबर,", "who": "", "voice": "narrator", "diary": false}, {"start": 506.29, "end": 510.02, "text": "लोहाघाट की एक धार पर पैंतालीस मिनट में क्या कर सकते हैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 510.02, "end": 514.28, "text": "अगर उनमें से एक गब्बर सिंह नेगी हो, और वो एक चरवाहे को जानता हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 514.73, "end": 515.41, "text": "घंटियाँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 515.41, "end": 521.86, "text": "गब्बर का दोस्त किशन, जो एबट माउंट के नीचे की ढलानों पर अपने मवेशी चराता था,", "who": "", "voice": "narrator", "diary": false}, {"start": 521.86, "end": 526.25, "text": "अँधेरे में छह गायें और दो बैल पहाड़ी पर ऊपर ले आया,", "who": "", "voice": "narrator", "diary": false}, {"start": 526.25, "end": 529.61, "text": "हर एक ने पीतल की एक बड़ी घंटी पहनी हुई।", "who": "", "voice": "narrator", "diary": false}, {"start": 529.81, "end": 530.83, "text": "पैसे नहीं चाहिए।", "who": "किशन", "voice": "kishan", "diary": false}, {"start": 531.03, "end": 532.13, "text": "किशन ने गब्बर से कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 532.33, "end": 533.82, "text": "बस कहानी सुनाना बाद में।", "who": "किशन", "voice": "kishan", "diary": false}, {"start": 534.27, "end": 534.97, "text": "कुत्ते।", "who": "", "voice": "narrator", "diary": false}, {"start": 534.97, "end": 540.92, "text": "किशन के दो कुत्ते, जो उन मवेशियों के पीछे कहीं भी चले जाते,", "who": "", "voice": "narrator", "diary": false}, {"start": 540.92, "end": 543.55, "text": "और किसी भी चीज़ पर भौंकते।", "who": "", "voice": "narrator", "diary": false}, {"start": 544.0, "end": 544.48, "text": "डोली।", "who": "", "voice": "narrator", "diary": false}, {"start": 544.48, "end": 551.63, "text": "गोलू की रिंग लाइट, गाड़ी से निकाले, शाओनी के फ़ालतू लाल दुपट्टे में लिपटी,", "who": "", "voice": "narrator", "diary": false}, {"start": 551.63, "end": 556.46, "text": "और एक लंबे बाँस के सिरे पर बँधी, धुंध में एक धीमी,", "who": "", "voice": "narrator", "diary": false}, {"start": 556.46, "end": 560.13, "text": "भयानक, काँपती लाल रोशनी में चमकती हुई।", "who": "", "voice": "narrator", "diary": false}, {"start": 560.58, "end": 561.04, "text": "आवाज़।", "who": "", "voice": "narrator", "diary": false}, {"start": 561.04, "end": 561.5, "text": "गब्बर।", "who": "", "voice": "narrator", "diary": false}, {"start": 561.5, "end": 565.64, "text": "जिनके बारे में पता चला, कि वो ऐड़ी का जागर गा सकते थे,", "who": "", "voice": "narrator", "diary": false}, {"start": 565.64, "end": 569.4, "text": "क्योंकि उनकी नानी ने भी उन्हें वो गाकर सुनाया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 569.85, "end": 572.32, "text": "क्षितिज ने अपने मेन्यू से नज़र उठाकर उन्हें देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 572.52, "end": 574.06, "text": "आपने तो कहा था, आप सुनते नहीं थे।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 574.51, "end": 575.29, "text": "नहीं सुनता था।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 575.49, "end": 577.41, "text": "गब्बर धुंध में घूर रहे थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 577.61, "end": 580.82, "text": "पर नानी गाती थी, जब मैं सो रहा होता था।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 580.82, "end": 581.72, "text": "बुख़ार में।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 581.72, "end": 583.29, "text": "सर्दी की रातों में।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 583.29, "end": 586.82, "text": "कुछ गीत कान से नहीं, नींद से अंदर जाते हैं।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 587.27, "end": 592.2, "text": "उन्होंने गला साफ़ किया, और पहली लाइन गुनगुनाई, बहुत धीरे से,", "who": "", "voice": "narrator", "diary": false}, {"start": 592.2, "end": 599.17, "text": "और वो सौ रुपये में भूतों की कहानियाँ बेचने वाले किसी टैक्सी ड्राइवर की आवाज़ नहीं थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 599.17, "end": 600.65, "text": "वो उससे पुरानी थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 601.1, "end": 605.02, "text": "आज पहली बार, नानी का गीत किसी काम आएगा।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 605.22, "end": 605.84, "text": "उन्होंने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 606.04, "end": 608.68, "text": "आज उसे ग़लत नहीं होने दूँगा।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 609.13, "end": 613.74, "text": "तब मुझे समझ आया, कि वो ये सिर्फ़ शाओनी के लिए नहीं कर रहे थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 613.74, "end": 616.38, "text": "वो ये उस फ़ोन कॉल के लिए कर रहे थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 616.38, "end": 617.67, "text": "उस साइकिल के लिए।", "who": "", "voice": "narrator", "diary": false}, {"start": 617.67, "end": 620.08, "text": "सीज़न है, के उन दो सालों के लिए।", "who": "", "voice": "narrator", "diary": false}, {"start": 620.78, "end": 622.77, "text": "उल्टे पैरों वाली आत्मा।", "who": "", "voice": "narrator", "diary": false}, {"start": 622.77, "end": 623.12, "text": "मैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 623.82, "end": 625.17, "text": "सफ़ेद शॉल में।", "who": "", "voice": "narrator", "diary": false}, {"start": 625.17, "end": 625.85, "text": "फिर से।", "who": "", "voice": "narrator", "diary": false}, {"start": 625.85, "end": 627.3, "text": "उल्टा चलते हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 627.75, "end": 631.19, "text": "क्षितिज ने मुझे गीली घास पर प्रैक्टिस करते देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 631.39, "end": 637.41, "text": "भाई, आप चैप्टर वन से, इस शॉल के साथ एक रिलेशनशिप में हो।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 637.86, "end": 639.38, "text": "शॉल मुझे समझती है।", "who": "", "voice": "narrator", "diary": false}, {"start": 639.58, "end": 641.96, "text": "मैंने पूरी गरिमा के साथ उससे कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 641.96, "end": 644.7, "text": "और उल्टा चलते हुए एक पेड़ से टकरा गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 646.2, "end": 648.8, "text": "आधी रात को, मैं क्षितिज की डायरी लिए,", "who": "", "voice": "narrator", "diary": false}, {"start": 648.8, "end": 651.96, "text": "पुराने बंगले की तरफ़ रास्ते पर अकेला ऊपर चला।", "who": "", "voice": "narrator", "diary": false}, {"start": 652.41, "end": 656.41, "text": "इमारत धार की चोटी पर खड़ी थी, एक लंबी, काली आकृति,", "who": "", "voice": "narrator", "diary": false}, {"start": 656.41, "end": 660.73, "text": "झुके हुए बरामदे, और टूटे दाँतों जैसी खिड़कियों के साथ।", "who": "", "voice": "narrator", "diary": false}, {"start": 660.73, "end": 664.01, "text": "उसके सामने घास पर दो एस-यू-वीज़ खड़ी थीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 664.01, "end": 668.81, "text": "बरामदे पर रोहन खड़ा था, एक लंबे, गहरे कोट में, बिल्कुल शांत,", "who": "", "voice": "narrator", "diary": false}, {"start": 668.81, "end": 672.49, "text": "जैसे किसी डिनर के मेहमान का इंतज़ार कर रहा हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 672.49, "end": 675.05, "text": "उसके पीछे उसके तीन आदमी खड़े थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 675.5, "end": 677.33, "text": "और उनके बग़ल में, भल्ला,", "who": "", "voice": "narrator", "diary": false}, {"start": 677.33, "end": 680.54, "text": "अपना एक भारी हाथ शाओनी की बाँह पर कसे हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 680.99, "end": 682.4, "text": "उसने मुझे देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 682.4, "end": 684.18, "text": "उसकी टोपी ग़ायब थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 684.18, "end": 689.06, "text": "उसका चेहरा खरोंचा हुआ, गंदा, और बेहद ग़ुस्से में था।", "who": "", "voice": "narrator", "diary": false}, {"start": 689.06, "end": 695.06, "text": "बल्कि, वो इस बात से नाराज़ दिख रही थी, कि मैंने इतनी देर लगा दी।", "who": "", "voice": "narrator", "diary": false}, {"start": 695.51, "end": 700.72, "text": "मैं अपनी ज़िंदगी में कभी किसी को अपने से नाराज़ देखकर इतना ख़ुश नहीं हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 701.17, "end": 701.72, "text": "प्रोफ़ेसर।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 701.92, "end": 703.28, "text": "रोहन ने नीचे आवाज़ दी।", "who": "", "voice": "narrator", "diary": false}, {"start": 703.48, "end": 704.09, "text": "पंक्चुअल।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 704.09, "end": 705.87, "text": "मैं इसकी इज़्ज़त करता हूँ।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 706.07, "end": 708.38, "text": "उसने अपना हाथ आगे बढ़ाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 708.58, "end": 709.06, "text": "डायरी।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 709.51, "end": 710.38, "text": "पहले शाओनी।", "who": "", "voice": "narrator", "diary": false}, {"start": 710.83, "end": 711.77, "text": "तो साथ में।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 711.77, "end": 712.7, "text": "आप ऊपर आइए।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 712.7, "end": 713.89, "text": "वो नीचे जाएगी।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 714.09, "end": 715.13, "text": "वो मुस्कुराया।", "who": "", "voice": "narrator", "diary": false}, {"start": 715.33, "end": 716.19, "text": "फ़िल्म की तरह।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 716.19, "end": 717.93, "text": "मुझे फ़िल्में बहुत पसंद हैं।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 718.38, "end": 719.71, "text": "मैं सीढ़ियाँ चढ़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 719.71, "end": 720.9, "text": "शाओनी नीचे उतरी।", "who": "", "voice": "narrator", "diary": false}, {"start": 720.9, "end": 724.82, "text": "भल्ला का हाथ आख़िरी मुमकिन सेकंड तक उसकी बाँह पर रहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 724.82, "end": 728.38, "text": "मैंने डायरी आगे बढ़ाई, और रोहन ने उसे पकड़ लिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 728.83, "end": 732.35, "text": "और धार के नीचे की धुंध से, घंटियों की आवाज़ आई।", "who": "", "voice": "narrator", "diary": false}, {"start": 732.8, "end": 734.11, "text": "एक घंटी नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 734.11, "end": 734.42, "text": "कई।", "who": "", "voice": "narrator", "diary": false}, {"start": 734.42, "end": 742.21, "text": "गहरी, धीमी, बेतरतीब पीतल की घंटियाँ, अँधेरे से पेड़ों के बीच से ऊपर आती हुईं,", "who": "", "voice": "narrator", "diary": false}, {"start": 742.21, "end": 745.86, "text": "झूलती हुईं, बजती हुईं, पास आती हुईं।", "who": "", "voice": "narrator", "diary": false}, {"start": 745.86, "end": 755.07, "text": "और उनके नीचे, एक आवाज़: एक आदमी की आवाज़, गहरी और काँपती हुई, पुरानी कुमाऊँनी में गाती हुई,", "who": "", "voice": "narrator", "diary": false}, {"start": 755.07, "end": 761.14, "text": "एक धीमी, भयानक, प्राचीन धुन, जो हवा की तरह उठती और गिरती थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 761.84, "end": 763.18, "text": "फिर कुत्ते भौंकने लगे।", "who": "", "voice": "narrator", "diary": false}, {"start": 763.88, "end": 769.42, "text": "धार के किनारे के ऊपर, धुंध से निकलकर, एक रोशनी उठी।", "who": "", "voice": "narrator", "diary": false}, {"start": 769.42, "end": 773.65, "text": "एक धीमी, लाल, झूलती हुई रोशनी, ऊँचे पर,", "who": "", "voice": "narrator", "diary": false}, {"start": 773.65, "end": 780.6, "text": "जैसे किसी बाँस पर उठाई गई हो, धीरे-धीरे बंगले की तरफ़ बढ़ती हुई।", "who": "", "voice": "narrator", "diary": false}, {"start": 781.05, "end": 782.97, "text": "बरामदे पर खड़े आदमी चुप हो गए।", "who": "", "voice": "narrator", "diary": false}, {"start": 783.42, "end": 785.18, "text": "उनमें से एक ने फुसफुसाकर कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 785.38, "end": 785.77, "text": "ऐड़ी।", "who": "", "voice": "local", "diary": false}, {"start": 786.22, "end": 792.91, "text": "और लाल रोशनी के पीछे, धुंध में, एक लंबी, सफ़ेद आकृति चलती हुई आई,", "who": "", "voice": "narrator", "diary": false}, {"start": 792.91, "end": 797.74, "text": "धीरे से, ख़ामोशी से, नामुमकिन तरीक़े से, उल्टी।", "who": "", "voice": "narrator", "diary": false}, {"start": 798.19, "end": 801.01, "text": "मैं कहना चाहूँगा, कि मैं शानदार था।", "who": "", "voice": "narrator", "diary": false}, {"start": 801.01, "end": 805.11, "text": "मैं एक होटल की शॉल में गीली घास पर उल्टा चल रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 805.11, "end": 810.34, "text": "लेकिन बरामदे से, उस धुंध में, उन घंटियों के साथ, उस आवाज़ के साथ,", "who": "", "voice": "narrator", "diary": false}, {"start": 810.34, "end": 815.01, "text": "मैं आपसे वादा करता हूँ: मैं दुनिया के अंत जैसा दिख रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 815.46, "end": 818.58, "text": "भल्ला का हाथ शाओनी की बाँह से छूट गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 819.03, "end": 820.94, "text": "उसने एक क़दम पीछे लिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 820.94, "end": 821.77, "text": "फिर एक और।", "who": "", "voice": "narrator", "diary": false}, {"start": 821.77, "end": 828.19, "text": "लाल रोशनी में उसका चेहरा, रज़ाई के नीचे लेटे एक सात साल के लड़के का चेहरा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 828.19, "end": 833.26, "text": "जो अपनी दादी से सुन रहा हो, कि रात को जंगल से क्या निकलता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 833.96, "end": 835.67, "text": "फिर वो मुड़ा, और भागा।", "who": "", "voice": "narrator", "diary": false}, {"start": 836.37, "end": 839.75, "text": "और भागते हुए, वो ऐड़ी नहीं चिल्ला रहा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 839.75, "end": 842.22, "text": "न भूत, न रोहन को पुकार रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 842.22, "end": 849.21, "text": "वो वही शब्द चिल्ला रहा था, जो शाओनी ने उसे भगुवाबासा में अँधेरे से फुसफुसाते सुना था,", "who": "", "voice": "narrator", "diary": false}, {"start": 849.21, "end": 853.49, "text": "अपनी भारी आवाज़ की पूरी ताक़त से, किसी बच्चे की तरह।", "who": "", "voice": "narrator", "diary": false}, {"start": 853.94, "end": 855.17, "text": "माफ़ कर दे!", "who": "भल्ला", "voice": "bhalla", "diary": false}, {"start": 855.17, "end": 856.95, "text": "माफ़ कर दे, भाई!", "who": "भल्ला", "voice": "bhalla", "diary": false}, {"start": 857.4, "end": 862.82, "text": "वो सीधा बरामदे के सिरे से अँधेरे में कूद गया, झाड़ियों को तोड़ता हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 862.82, "end": 866.75, "text": "और हमने उसे धार के दूसरी तरफ़ पूरा नीचे जाते सुना,", "who": "", "voice": "narrator", "diary": false}, {"start": 866.75, "end": 869.02, "text": "आवाज़ छोटी, और छोटी होती हुई।", "who": "", "voice": "narrator", "diary": false}, {"start": 869.02, "end": 872.01, "text": "बाक़ी तीन आदमियों ने एक-दूसरे को देखा,", "who": "", "voice": "narrator", "diary": false}, {"start": 872.01, "end": 874.6, "text": "हिम्मत हारी, और उसके पीछे भाग गए।", "who": "", "voice": "narrator", "diary": false}, {"start": 875.05, "end": 878.02, "text": "और इस सबके बीच, शाओनी ने वो किया,", "who": "", "voice": "narrator", "diary": false}, {"start": 878.02, "end": 882.43, "text": "जो आज तक किसी ने किया हुआ सबसे शाओनी वाला काम है।", "who": "", "voice": "narrator", "diary": false}, {"start": 882.43, "end": 883.6, "text": "वो भागी नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 883.6, "end": 886.48, "text": "वो आगे बढ़ी, रोहन की कलाई पकड़ी,", "who": "", "voice": "narrator", "diary": false}, {"start": 886.48, "end": 889.54, "text": "वही, जिसमें डायरी थी, और मरोड़ दी।", "who": "", "voice": "narrator", "diary": false}, {"start": 889.99, "end": 893.05, "text": "रोहन जितना दिखता था, उससे तेज़ था।", "who": "", "voice": "narrator", "diary": false}, {"start": 893.05, "end": 897.91, "text": "उसने उसे ज़ोर से धक्का दिया, और वो सीढ़ियों पर गिर गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 897.91, "end": 902.68, "text": "जब तक मैं उसके पास पहुँचा, वो जा चुका था: घास के पार,", "who": "", "voice": "narrator", "diary": false}, {"start": 902.68, "end": 906.55, "text": "सबसे पास वाली एस-यू-वी में, इंजन गरजता हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 907.25, "end": 908.29, "text": "डायरी के साथ।", "who": "", "voice": "narrator", "diary": false}, {"start": 908.99, "end": 918.39, "text": "एस-यू-वी की रोशनियाँ धुंध के पार घूमीं, मवेशियों के पार, पहाड़ी पर गब्बर के पार, जिनका मुँह अब भी गाने के बीच में खुला था,", "who": "", "voice": "narrator", "diary": false}, {"start": 918.39, "end": 922.63, "text": "बाँस का डंडा पकड़े गोलू के पार, जिसके ऊपर रिंग लाइट थी,", "who": "", "voice": "narrator", "diary": false}, {"start": 922.63, "end": 925.79, "text": "और फिर वो चली गईं, सड़क से नीचे, रात में।", "who": "", "voice": "narrator", "diary": false}, {"start": 926.24, "end": 927.85, "text": "घंटियाँ रुक गईं।", "who": "", "voice": "narrator", "diary": false}, {"start": 927.85, "end": 929.26, "text": "कुत्ते रुक गए।", "who": "", "voice": "narrator", "diary": false}, {"start": 929.26, "end": 930.98, "text": "धुंध पास सिमट आई।", "who": "", "voice": "narrator", "diary": false}, {"start": 931.43, "end": 936.49, "text": "बरामदे की सबसे निचली सीढ़ी पर, जहाँ भल्ला खड़ा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 936.49, "end": 939.74, "text": "एक बहुत बड़ा, काला जूता पड़ा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 940.19, "end": 944.29, "text": "क्षितिज अँधेरे से रास्ते पर ऊपर आया, उसे उठाया,", "who": "", "voice": "narrator", "diary": false}, {"start": 944.29, "end": 947.7, "text": "और पेशेवर दिलचस्पी के साथ उसकी जाँच की।", "who": "", "voice": "narrator", "diary": false}, {"start": 947.9, "end": 949.19, "text": "उसने जूता छोड़ दिया।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 949.39, "end": 950.56, "text": "उसने मुझे रिपोर्ट किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 950.76, "end": 951.96, "text": "साइज़ ट्वेल्व।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 952.41, "end": 957.56, "text": "फिर उसने रोहन की टेल-लाइट्स को नीचे मोड़ पर ग़ायब होते देखा,", "who": "", "voice": "narrator", "diary": false}, {"start": 957.56, "end": 960.56, "text": "और मेरे ख़ाली हाथ देखे, और समझ गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 961.01, "end": 964.56, "text": "शाओनी सीढ़ियों पर उठकर बैठी, अपनी कोहनी मलते हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 964.56, "end": 966.15, "text": "उसने अपने भाई को देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 966.15, "end": 967.52, "text": "उसने सॉरी नहीं कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 967.52, "end": 971.93, "text": "वो अपनी लॉजिक वाली आवाज़ में बोली, जो बस ज़रा सी काँप रही थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 972.38, "end": 973.21, "text": "बोतलें समझे?", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 973.66, "end": 974.43, "text": "चार लोग।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 974.63, "end": 975.82, "text": "क्षितिज ने उससे कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 976.02, "end": 977.88, "text": "एक बोतल टेढ़ी: भल्ला।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 977.88, "end": 980.72, "text": "सब गाड़ी की तरफ़ इशारा करते हुए।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 981.17, "end": 981.56, "text": "गुड।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 981.76, "end": 982.79, "text": "वो खड़ी हो गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 982.99, "end": 983.46, "text": "डायरी?", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 983.91, "end": 986.89, "text": "क्षितिज ने उस अँधेरी सड़क की तरफ़ नीचे देखा,", "who": "", "voice": "narrator", "diary": false}, {"start": 986.89, "end": 988.25, "text": "जहाँ टेल-लाइट्स थीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 988.7, "end": 989.58, "text": "उसमें सब था।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 989.78, "end": 991.04, "text": "उसने धीरे से कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 991.24, "end": 992.7, "text": "कुंदन दादा।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 992.7, "end": 993.64, "text": "धना जी।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 993.64, "end": 994.3, "text": "छानी।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 994.3, "end": 995.1, "text": "खलिया।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 995.8, "end": 997.14, "text": "किसी ने कुछ नहीं कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 997.84, "end": 1002.52, "text": "फिर गोलू पहाड़ी से उतरकर हमारे पास आया, बाँस का डंडा नीचे किया,", "who": "", "voice": "narrator", "diary": false}, {"start": 1002.52, "end": 1007.05, "text": "रिंग लाइट से लाल दुपट्टा खोला, और क्षितिज की तरफ़ कुछ बढ़ाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1007.5, "end": 1009.28, "text": "एक बिल्कुल नई नोटबुक।", "who": "", "voice": "narrator", "diary": false}, {"start": 1009.28, "end": 1010.04, "text": "भूरा कवर।", "who": "", "voice": "narrator", "diary": false}, {"start": 1010.04, "end": 1011.73, "text": "अब भी प्लास्टिक में।", "who": "", "voice": "narrator", "diary": false}, {"start": 1012.18, "end": 1012.95, "text": "गाड़ी में रखता हूँ।", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 1013.15, "end": 1014.34, "text": "गोलू ने उससे कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1014.54, "end": 1015.75, "text": "व्लॉग के नोट्स के लिए।", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 1015.95, "end": 1016.75, "text": "एक पॉज़।", "who": "", "voice": "narrator", "diary": false}, {"start": 1016.95, "end": 1018.54, "text": "तुम्हें ज़्यादा ज़रूरत है।", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 1018.99, "end": 1020.72, "text": "क्षितिज ने उसे ले लिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1020.72, "end": 1022.29, "text": "उसने प्लास्टिक फाड़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1022.29, "end": 1026.11, "text": "उसने उसका पहला पन्ना खोला, अपने पेन का ढक्कन हटाया,", "who": "", "voice": "narrator", "diary": false}, {"start": 1026.11, "end": 1027.76, "text": "और अँधेरे और धुंध में,", "who": "", "voice": "narrator", "diary": false}, {"start": 1027.76, "end": 1030.99, "text": "उधार की एक गाय के बग़ल में खड़े होकर, लिखा:", "who": "", "voice": "narrator", "diary": false}, {"start": 1031.44, "end": 1032.28, "text": "डे ट्वेल्व।", "who": "", "voice": "narrator", "diary": false}, {"start": 1032.28, "end": 1032.89, "text": "लोहाघाट।", "who": "", "voice": "narrator", "diary": false}, {"start": 1032.89, "end": 1034.81, "text": "आर. के पास मेरी डायरी है।", "who": "", "voice": "narrator", "diary": false}, {"start": 1034.81, "end": 1037.26, "text": "आर. को खलिया के बारे में पता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 1037.96, "end": 1039.14, "text": "तो अब ये एक रेस है।", "who": "", "voice": "narrator", "diary": false}, {"start": 1039.84, "end": 1042.44, "text": "क्षितिज की डायरी से, नई वाली।", "who": "", "voice": "narrator", "diary": true}, {"start": 1042.44, "end": 1044.41, "text": "डे ट्वेल्व, एबट माउंट।", "who": "", "voice": "narrator", "diary": true}, {"start": 1044.86, "end": 1049.47, "text": "महेश, गब्बर भैया के कज़िन, ने पहले दिन से आर. के पैसे लिए।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1049.47, "end": 1053.52, "text": "आर. को द्रोणागिरी और इजा के गाँव के बारे में बताया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1053.52, "end": 1058.53, "text": "कल रात गब्बर भैया ने महेश को बताया, कि हम गंगोलीहाट जा रहे हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1058.53, "end": 1063.23, "text": "जब हम गुफा से निकले, आर. के आदमी पहले से इंतज़ार कर रहे थे।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1063.23, "end": 1066.72, "text": "आज उन्होंने ख़ुद, ग़ुस्से में, फिर बता दिया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1066.72, "end": 1068.71, "text": "गब्बर भैया बहुत दुखी हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1068.71, "end": 1070.38, "text": "गोलू कभी लीक नहीं था।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1070.38, "end": 1071.42, "text": "दीदी सही थीं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1071.42, "end": 1074.44, "text": "मैंने डे सिक्स पर महेश को काट दिया था,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1074.44, "end": 1078.02, "text": "क्योंकि वो गब्बर भैया के साथ साइकिल चलाता था।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1078.02, "end": 1081.51, "text": "नियम: लोगों को अच्छा होने की वजह से मत काटो।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1081.96, "end": 1085.47, "text": "भल्ला चिल्लाता हुआ भागा, माफ़ कर दे, भाई!", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1085.47, "end": 1087.78, "text": "वही शब्द, जो भगुवाबासा में।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1087.78, "end": 1089.32, "text": "ऐड़ी से नहीं डरता।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1089.32, "end": 1094.03, "text": "किसी ऐसे से डरता है, जिसे उसे लगता है, ऐड़ी ला रहे हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1094.48, "end": 1096.24, "text": "गोलू ने पहली रात, सवॉय में,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1096.24, "end": 1099.12, "text": "आर. की एस-यू-वी पर जी-पी-एस ट्रैकर लगाया था।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1099.12, "end": 1101.54, "text": "वो बारह दिन से आर. का पीछा कर रहा है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1101.54, "end": 1101.93, "text": "क्यों?", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1101.93, "end": 1103.24, "text": "वो कहता है, बाद में।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1103.69, "end": 1105.22, "text": "ऐड़ी: देखो, तो मरो।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1105.22, "end": 1106.83, "text": "भल्ला ने यक़ीन किया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1106.83, "end": 1107.72, "text": "भल्ला भागा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1107.72, "end": 1110.47, "text": "साइज़ ट्वेल्व का एक जूता छोड़ गया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1110.92, "end": 1115.1, "text": "दीदी की बोतलें: चार आदमी, एक टेढ़ी, यानी भल्ला,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1115.1, "end": 1118.03, "text": "सब गाड़ी की तरफ़ इशारा करती हुईं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1118.03, "end": 1119.18, "text": "वो आज़ाद हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1119.18, "end": 1121.67, "text": "उन्होंने आर. की कलाई मरोड़ी।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1121.67, "end": 1124.69, "text": "वो नाराज़ हैं, कि वो काम नहीं आया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1125.14, "end": 1127.64, "text": "आर. के पास मेरी पुरानी डायरी है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1127.64, "end": 1128.89, "text": "उसमें सब कुछ है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1128.89, "end": 1131.46, "text": "खलिया बुग्याल पर कुंदन की झोपड़ी।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1131.46, "end": 1132.71, "text": "वो आज रात जाएगा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1132.71, "end": 1134.51, "text": "हमें और तेज़ जाना होगा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1134.96, "end": 1138.88, "text": "पार्थ भाई उल्टा चलते हुए दो बार पेड़ से टकराए।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1138.88, "end": 1142.21, "text": "मैं इसे सटीकता के लिए शामिल कर रहा हूँ।", "who": "क्षितिज", "voice": "kshitij", "diary": true}], "scenes": [{"at": 18.44, "bed": "threat"}, {"at": 54.4, "bed": "sinking"}, {"at": 124.78, "bed": "tender"}, {"at": 145.09, "bed": "suspense"}, {"at": 161.58, "bed": "discovery"}, {"at": 201.54, "bed": "tender"}, {"at": 264.07, "bed": "roadnight"}, {"at": 299.57, "bed": "fog"}, {"at": 397.18, "bed": "plan"}, {"at": 423.64, "bed": "lore"}, {"at": 498.37, "bed": "caper"}, {"at": 573.31, "bed": "tender"}, {"at": 619.58, "bed": "caper"}, {"at": 645.0, "bed": "vigil"}, {"at": 699.97, "bed": "threat"}, {"at": 727.63, "bed": "airi"}, {"at": 832.76, "bed": "chase"}, {"at": 925.04, "bed": "stillness"}, {"at": 938.99, "bed": "caper"}, {"at": 951.21, "bed": "sinking"}, {"at": 996.64, "bed": "tender"}, {"at": 1030.24, "bed": "heroic"}, {"at": 1038.64, "bed": "diary"}, {"at": 1038.64, "bed": "diary"}], "hits": [{"at": 19.49, "fx": "ping"}, {"at": 146.14, "fx": "suv"}, {"at": 149.62, "fx": "cardoor"}, {"at": 188.58, "fx": "sting"}, {"at": 422.48, "fx": "drumhit"}, {"at": 514.58, "fx": "bell"}, {"at": 534.12, "fx": "dogs"}, {"at": 587.12, "fx": "airisong"}, {"at": 637.71, "fx": "thud"}, {"at": 718.23, "fx": "steps_slow"}, {"at": 761.69, "fx": "airisong"}, {"at": 761.69, "fx": "dogs"}, {"at": 786.07, "fx": "sting"}, {"at": 857.25, "fx": "crash"}, {"at": 889.84, "fx": "thud"}, {"at": 907.1, "fx": "carstart"}, {"at": 907.1, "fx": "sting"}, {"at": 1018.84, "fx": "page"}, {"at": 1037.81, "fx": "sting"}, {"at": 1094.33, "fx": "sting_light"}, {"at": 1124.99, "fx": "sting"}], "next": {"label": "एपिसोड 13", "en": "The Tigress Nobody Could Stop", "hook": "गोलू कौन है? चंपावत की एक सुबह, और एक सच, जो चौदह महीने से छुपा था।"}};
